// augments the global `Error` like effect does
declare global {
  interface Error {
    readonly '~augments/severity'?: 'error' | 'warn'
    readonly '~augments/reported': boolean
  }
}

export interface Reporter {
  report(error: Error): void
}

/** Declared like effect's opaque schema types: the constructor does not create the interface */
export interface Opaque {
  tags: Set<string>
}

export declare const Opaque: { new (_: never): {} }

/** Declared like a library class */
export interface Session {
  readonly id: string
  tags: Set<string>
}

export declare const Session: { new (): Session }
